        self.client = client or httpx.Client(timeout=30.0, follow_redirects=False)
        self._owns_client = client is None
        self.validate_dns = validate_dns
        self.github_token = github_token
        self.hugging_face_token = hugging_face_token
        self.zenodo = ZenodoAcquirer(
            cache_dir,
            max_asset_bytes=max_asset_bytes,
            client=self.client,
            validate_dns=validate_dns,
        )

    def close(self) -> None:
        self.zenodo.close()
        if self._owns_client:
            self.client.close()

    def has_verified_content(self, content_sha256: str, size_bytes: int) -> bool:
        return self.zenodo.has_verified_content(content_sha256, size_bytes)

    def verified_content_path(self, content_sha256: str) -> Path:
        path = self.content_dir / content_sha256[:2] / content_sha256
        if not path.is_file():
            raise AcquisitionError("Verified content is unavailable")
        return path

    def acquire(self, manifest: ApprovedManifest, asset: ManifestAsset) -> AcquiredAsset:
        if manifest.source_kind is SourceKind.ZENODO:
            return self.zenodo.acquire(SourceKind.ZENODO, asset)
        if manifest.source_kind is SourceKind.GITHUB:
            return self._github(manifest, asset)
        if manifest.source_kind is SourceKind.HUGGING_FACE:
            return self._hugging_face(manifest, asset)
        raise AcquisitionError("Approved source provider is unsupported")

    def _github(self, manifest: ApprovedManifest, asset: ManifestAsset) -> AcquiredAsset:
        locator = _GITHUB_LOCATOR.fullmatch(asset.provider_locator)
        canonical = urlsplit(str(manifest.canonical_url))
        if locator is None or not _safe_name(asset.name):
            raise AcquisitionError("GitHub asset identity is invalid")
        owner, repo, blob_sha = locator.groups()
        if canonical.path.rstrip("/") != f"/{owner}/{repo}" or not re.fullmatch(
            r"[a-f0-9]{40}", manifest.source_revision
        ):
            raise AcquisitionError("GitHub repository or commit identity is invalid")
        api = f"https://api.github.com/repos/{owner}/{repo}"
        expected_download = f"{api}/git/blobs/{blob_sha}"
        if str(asset.download_url).rstrip("/") != expected_download:
            raise AcquisitionError("GitHub blob URL does not match its approved identity")
        headers = {
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2026-03-10",
        }
        if self.github_token:
            headers["Authorization"] = f"Bearer {self.github_token}"
        metadata_url = (
            f"{api}/contents/{quote(asset.name, safe='/')}?ref={manifest.source_revision}"
        )
        metadata = self._json(metadata_url, headers, lambda host: host == "api.github.com")
        if (
            metadata.get("type") != "file"
            or metadata.get("sha") != blob_sha
            or metadata.get("size") != asset.size_bytes
        ):
            raise AcquisitionError("GitHub commit does not contain the approved blob")
        return self._download(
            expected_download,
            asset,
            headers=headers | {"Accept": "application/vnd.github.raw+json"},
            allowed_host=lambda host: host == "api.github.com",
            expected_git_blob=blob_sha,
        )

    def _hugging_face(self, manifest: ApprovedManifest, asset: ManifestAsset) -> AcquiredAsset:
        locator = _HF_LOCATOR.fullmatch(asset.provider_locator)
        canonical = urlsplit(str(manifest.canonical_url))
        if locator is None or not _safe_name(asset.name):
            raise AcquisitionError("Hugging Face asset identity is invalid")
        namespace, revision, name = locator.groups()
        if (
            canonical.path.rstrip("/") != f"/datasets/{namespace}"
            or revision != manifest.source_revision
            or name != asset.name
        ):
            raise AcquisitionError("Hugging Face dataset revision identity is invalid")
        self.jobs = jobs
        self.cache_dir = self.data_dir / "cache"
        self.registry_root = self.data_dir / "timef"

    @staticmethod
    def onboarding_job_id(ingestion_id: str) -> str:
        return f"job-{ingestion_id.replace('-', '')}"

    def _service(self, ingestion_id: str) -> OnboardingOrchestrator:
        ingestion = self.jobs.get(ingestion_id)
        backend = IngestionOnboardingBackend(
            ingestion,
            self.jobs,
            GenericTimeFBuilder(cache_dir=self.cache_dir, registry_root=self.registry_root),
            SpecializedDispatcher(cache_dir=self.cache_dir, registry_root=self.registry_root),
        )
        return OnboardingOrchestrator(self.data_dir / "onboarding_jobs", backend)

    def can_onboard(self, ingestion_id: str) -> bool:
        try:
            self._service(ingestion_id)
        except GenericImportError:
            return False
        return True

    def start(self, ingestion_id: str) -> IngestionJob:
        ingestion = self.jobs.get(ingestion_id)
        service = self._service(ingestion_id)
        job_id = self.onboarding_job_id(ingestion_id)
        directory = service.store.job_dir(job_id)
        if directory.exists():
            onboarding = service.get_job(job_id)
        else:
            descriptor = source_descriptor_from_acquisition(
                ingestion,
                self.jobs.list_receipts(ingestion_id),
                self.jobs.list_resources(ingestion_id),
                cache_dir=self.cache_dir,
            )
            onboarding = service.create_job(descriptor, job_id=job_id)
        self._sync(ingestion_id, onboarding)
        onboarding = service.run_job(job_id)
        return self._sync(ingestion_id, onboarding)

    def continue_job(self, ingestion_id: str) -> IngestionJob:
        service = self._service(ingestion_id)
        onboarding = service.continue_job(self.onboarding_job_id(ingestion_id))
        return self._sync(ingestion_id, onboarding)

    def resolve(self, ingestion_id: str, request: HumanResolutionRequest) -> dict[str, Any]:
        service = self._service(ingestion_id)
        onboarding = service.resolve_blocker(
            self.onboarding_job_id(ingestion_id),
            field_path=request.field_path,
            value=request.value,
            approved_by=request.approved_by,
            rationale=request.rationale,
            source=request.source,
        )
        self._sync(ingestion_id, onboarding)
        return self.view(ingestion_id)

    def view(self, ingestion_id: str) -> dict[str, Any]:
        ingestion = self.jobs.get(ingestion_id)
        if not ingestion.onboarding_job_id:
            raise IngestionJobConflict("Ingestion has not reached semantic onboarding")
        job = self._service(ingestion_id).get_job(ingestion.onboarding_job_id)
        return {
            "ingestion_id": ingestion_id,
            "job_id": job.job_id,
            "status": job.status.value.upper(),
            "stage": job.stage.value.upper(),
            "blockers": [asdict(item) for item in job.blockers],
            "artifacts": {
                name: {
                    "name": ref.name,
                    "stage": ref.stage.upper(),
                    "media_type": ref.media_type,
                    "sha256": ref.sha256,
                }
                for name, ref in job.artifacts.items()
            },
            "error": asdict(job.error) if job.error else None,
            "result": job.result,
        }

    def _sync(self, ingestion_id: str, job) -> IngestionJob:
        blockers = [asdict(item) for item in job.blockers]
        if job.status is JobStatus.NEEDS_HUMAN_RESOLUTION:
            state = IngestionState.NEEDS_HUMAN_RESOLUTION
            message = "Semantic onboarding needs explicit human resolution"
        elif job.status is JobStatus.COMPLETED:
            state = IngestionState.READY
            message = "TimeF dataset passed orchestrated load and verification"
        elif job.status is JobStatus.FAILED:
            state = IngestionState.FAILED
            message = f"Onboarding failed during {job.error.stage if job.error else job.stage.value}"
        elif job.stage.value == "connector_ready":
            state = IngestionState.CONNECTOR_READY
            message = "Human resolutions accepted; connector stages are queued"
        else:
            state = IngestionState.ONBOARDING
            message = f"Onboarding stage: {job.stage.value}"
        return self.jobs.set_onboarding_state(
            ingestion_id,
            onboarding_job_id=job.job_id,
            onboarding_status=job.status.value.upper(),
            onboarding_stage=job.stage.value.upper(),
            blockers=blockers,
            state=state,
            message=message,
        )


class OnboardingWorker:
    def __init__(self, coordinator: IngestionOnboardingCoordinator) -> None:
        self.coordinator = coordinator

    def recover_interrupted(self) -> int:
        return self.coordinator.jobs.requeue_interrupted_onboarding()

from __future__ import annotations

import argparse
import os
import time
from pathlib import Path

from .archive import SafeArchiveExtractor
from .dispatch import SpecializedDispatcher
from .inventory import ResourceInventory
from .jobs import IngestionJobStore
from .onboarding import IngestionOnboardingCoordinator, OnboardingWorker
from .providers import ProviderAcquirer
from .service import HttpApprovedSourceResolver
from .worker import AcquisitionWorker


def main() -> int:
    parser = argparse.ArgumentParser(description="Acquire queued approved dataset assets")
    parser.add_argument("--once", action="store_true", help="Process at most one queued job")
    parser.add_argument("--poll-seconds", type=float, default=2.0)
    args = parser.parse_args()
    if args.poll_seconds <= 0:
        parser.error("--poll-seconds must be positive")

    data_dir = Path(os.environ.get("INGESTION_DATA_DIR", "var/ingestion"))
    jobs = IngestionJobStore(data_dir / "ingestions.sqlite3")
    resolver = HttpApprovedSourceResolver(
        os.environ.get("INGESTION_SOURCING_API_URL", "http://127.0.0.1:8001")
    )
    acquirer = ProviderAcquirer(
        data_dir / "cache",
        github_token=os.environ.get("GITHUB_TOKEN"),
        hugging_face_token=os.environ.get("HF_TOKEN"),
    )
    dispatcher = SpecializedDispatcher(
        cache_dir=data_dir / "cache",
        registry_root=data_dir / "timef",
    )
    onboarding = IngestionOnboardingCoordinator(data_dir, jobs)
    worker = AcquisitionWorker(
        jobs,
        resolver,
        acquirer,
        extractor=SafeArchiveExtractor(data_dir / "cache"),
        inventory=ResourceInventory(),
        dispatcher=dispatcher,
        onboarding=onboarding,
    )
    onboarder = OnboardingWorker(onboarding)
    try:
        worker.recover_interrupted()
        onboarder.recover_interrupted()
        while True:
            processed = worker.run_once() or onboarder.run_once()
            if args.once:
                return 0
            if processed is None:
                time.sleep(args.poll_seconds)
    except KeyboardInterrupt:
        return 0
    finally:
        acquirer.close()
        resolver.close()
        jobs.close()


if __name__ == "__main__":
    raise SystemExit(main())
