            "21927431.r5",
        )
        with self.assertRaises(SpecializedDispatchError):
            self.dispatcher.resolve(bad_revision)

        bad_license = bad_revision.model_copy(
            update={"source_revision": "21927431.r4", "dataset_license_id": "MIT"}
